/// Spec does, told what the code step did. Each step knows the one it was
/// sent from.
fn chain_next(task: &PromptTask) -> Option<(String, Sending)> {
    let sent = &task.sent;
    let (mode, code_task, post_build_update) = match sent.mode? {
        SendMode::Both => (
            SendMode::Code,
            CodeTask {
                prompt: task.text.to_string(),
